import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·17","description":"易小帖 - 卷三·17","frontmatter":{"title":"卷三·17","description":"易小帖 - 卷三·17"},"headers":[],"relativePath":"classics/yixiaotie/085.md","filePath":"classics/yixiaotie/085.md"}'),o={name:"classics/yixiaotie/085.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·17",tabindex:"-1"},[r("卷三·17 "),e("a",{class:"header-anchor",href:"#卷三·17","aria-label":"Permalink to “卷三·17”"},"​")],-1),e("p",null,"虞仲翔以納甲闡五十五數，謂甲乾乙坤，相得合木。丙艮丁兌，相得合火。戊坎己離，相得合土。庚震辛巽，相得合金。天壬地癸，相得合水。其言天地者即乾坤也。蓋十日之數，自甲至癸，即自一至十。乾納甲壬，以甲一壬九，皆乾數也。坤納乙癸，以乙二癸十，皆坤數也。自是而震納庚數七，巽納辛數八，坎納戊數五，離納己數六，艮納丙數三，兌納丁數四，於以合於五位相得，原數亦俱，彷佛此本漢儒舊說，而宋人多宗之者。若劉牧竊襲虞鄭兩家之意，以一六合坎，二七合火，三八合木，四九合金，其為八純者本之康成。己得四十數而以中央五十則倣之仲翔天地之數，以為天九地六合為十五，共五十五數，則天地乾坤各分位數，與虞氏之祗合卦氣者又有礙矣。天地即乾坤，支幹圜轉，位無一定，故數無一名，豈可以《大傳》所定卦位，而乾坤天地，雜見錯出如是者，陳氏之徒，務為新異，而不知其不合如此。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
